package com.bri.evtrip;

import android.app.*;
import android.os.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import java.util.*;

public class MainActivity extends Activity {
  final int BLUE=Color.rgb(23,105,224), GREEN=Color.rgb(20,145,92), ORANGE=Color.rgb(205,126,0), RED=Color.rgb(198,54,52), INK=Color.rgb(24,31,42), MUTED=Color.rgb(91,102,118), BG=Color.rgb(247,249,252), SURFACE=Color.WHITE;
  LinearLayout root, content; TextView title, subtitle, feedback; int battery=68; boolean online=false; String active="Zembo · Bugolobi", brand="Zembo", energy="Battery swap", report="Open and working"; ArrayList<String> reports=new ArrayList<>();
  @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(BG); getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR); showTrip();}
  TextView text(String s,int sp,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(c);v.setPadding(0,3,0,3);return v;}
  GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}
  void pad(View v,int l,int t,int r,int b){v.setPadding(l,t,r,b);} int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
  LinearLayout box(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);v.setPadding(dp(12),dp(10),dp(12),dp(10));v.setBackground(bg(SURFACE,dp(14)));v.setElevation(dp(1));return v;}
  Button btn(String s,boolean main){Button b=new Button(this);b.setText(s);b.setTextSize(12);b.setAllCaps(false);b.setTextColor(main?Color.WHITE:BLUE);b.setBackground(bg(main?BLUE:Color.rgb(232,240,255),dp(18)));return b;}
  void base(String t,String st){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(15),dp(13),dp(15),dp(12));root.setBackgroundColor(BG); title=text(t,22,INK); title.setTypeface(null,1);subtitle=text(st,12,MUTED);root.addView(title);root.addView(subtitle);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);root.addView(content,new LinearLayout.LayoutParams(-1,0,1));feedback=text("Ready for a cautious route.",12,MUTED);feedback.setGravity(Gravity.CENTER);root.addView(feedback);setContentView(root);}
  void add(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,0);content.addView(v,p);}
  TextView pill(String s,int color){TextView p=text(s,11,color);p.setPadding(dp(8),dp(4),dp(8),dp(4));p.setBackground(bg(color==GREEN?Color.rgb(230,247,238):Color.rgb(255,243,223),dp(15)));return p;}
  void showTrip(){base("Kampala energy trip","Local maps, battery safety and verified refill choices"); LinearLayout map=box();map.setBackground(bg(Color.rgb(229,240,255),dp(18)));TextView route=text("KAMPALA LOCAL ROUTE",11,MUTED);route.setTypeface(null,1);map.addView(route);TextView line=text("●  You   ┄ ┄ ┄ ┄   ◉  "+active,19,BLUE);line.setPadding(0,dp(35),0,dp(34));map.addView(line);TextView batt=text("Battery  "+battery+"%",14,INK);batt.setGravity(Gravity.RIGHT);map.addView(batt);add(map);
    LinearLayout stats=new LinearLayout(this);stats.setOrientation(LinearLayout.HORIZONTAL); String[] a={Math.round(battery*.62)+" km\nconservative range",Math.max(0,battery-37)+"%\narrival reserve",compatible()?"1\ncompatible nearby":"0\ncompatible nearby"};for(String s:a){LinearLayout q=box();String[] z=s.split("\\n");TextView n=text(z[0],17,INK);n.setTypeface(null,1);q.addView(n);q.addView(text(z[1],10,MUTED));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(0,-2,1);qp.setMargins(0,0,dp(6),0);stats.addView(q,qp);}add(stats);
    LinearLayout sync=box();sync.setOrientation(LinearLayout.HORIZONTAL);sync.addView(text(online?"●  Live updates active":"●  Offline pack in use",12,online?GREEN:ORANGE));sync.addView(text(online?"  station updates refresh when available":"  maps and saved stations keep working",11,MUTED));add(sync);
    LinearLayout station=box();LinearLayout head=new LinearLayout(this);head.setOrientation(LinearLayout.HORIZONTAL);TextView name=text(active,15,INK);name.setTypeface(null,1);head.addView(name,new LinearLayout.LayoutParams(0,-2,1));head.addView(pill(compatible()?"Compatible":"Not compatible",compatible()?GREEN:ORANGE));station.addView(head);station.addView(text(brand+" · "+energy+" · last station detail saved",11,MUTED));station.addView(text(compatible()?"Reachable with conservative reserve. Status must still be checked at arrival.":"This station is not a confirmed match for this profile.",11,compatible()?GREEN:RED));add(station);
    LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button routeBtn=btn("Prepare safe route",true);routeBtn.setOnClickListener(v->{feedback.setText(compatible()?"Safe route prepared to "+active+". Arrival reserve: "+Math.max(0,battery-37)+"%.":"Not compatible. Choose a confirmed network before routing.");});actions.addView(routeBtn,new LinearLayout.LayoutParams(0,-2,1));Button reportBtn=btn("Report station",false);reportBtn.setOnClickListener(v->showReport());actions.addView(reportBtn,new LinearLayout.LayoutParams(0,-2,1));Button vehicle=btn("Vehicle",false);vehicle.setOnClickListener(v->showVehicle());actions.addView(vehicle,new LinearLayout.LayoutParams(0,-2,1));add(actions);
    Button data=btn(online?"Use offline data":"Use live updates",false);data.setOnClickListener(v->{online=!online;showTrip();});add(data);}
  boolean compatible(){return energy.equals("Battery swap")&&((brand.equals("Zembo")&&active.startsWith("Zembo"))||(brand.equals("GOGO")&&active.startsWith("GOGO"))||(brand.equals("Spiro")&&active.startsWith("Spiro")));}
  void showVehicle(){base("Your vehicle profile","Set once. The route engine filters the rest.");LinearLayout b=box();b.addView(text("Battery now: "+battery+"%",20,INK));SeekBar bar=new SeekBar(this);bar.setMax(95);bar.setProgress(battery-5);bar.setOnSeekBarChangeListener(new android.widget.SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int p,boolean f){battery=p+5;}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){showVehicle();}});b.addView(bar);b.addView(text("Saved estimate. It is never labelled live without a real BMS connection.",11,MUTED));add(b);
    add(text("Battery network / brand",12,MUTED));Spinner brands=new Spinner(this);String[] bs={"Zembo","GOGO","Spiro","Tesla","Other / manual"};brands.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,bs));brands.setSelection(Arrays.asList(bs).indexOf(brand));add(brands);add(text("Energy path",12,MUTED));Spinner energies=new Spinner(this);String[] es={"Battery swap","Plug charging","Both"};energies.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,es));energies.setSelection(Arrays.asList(es).indexOf(energy));add(energies);
    LinearLayout note=box();note.setBackground(bg(Color.rgb(255,243,223),dp(14)));note.addView(text("Compatibility is strict",14,INK));note.addView(text("Only the exact approved swap network can be recommended. Similar batteries, plug shapes or voltage are not a safe match.",12,MUTED));add(note);
    LinearLayout actions=new LinearLayout(this);Button save=btn("Save vehicle profile",true);save.setOnClickListener(v->{brand=(String)brands.getSelectedItem();energy=(String)energies.getSelectedItem();showTrip();feedback.setText("Vehicle profile saved on this phone.");});actions.addView(save,new LinearLayout.LayoutParams(0,-2,1));Button back=btn("Back",false);back.setOnClickListener(v->showTrip());actions.addView(back,new LinearLayout.LayoutParams(0,-2,1));add(actions);}
  void showReport(){base("Station field report","Saved on-device first, then reviewed before it affects the map.");LinearLayout info=box();info.addView(text(active,16,INK));info.addView(text("Record only what you personally observed.",11,MUTED));add(info);RadioGroup choices=new RadioGroup(this);String[] rs={"Open and working","Swap/charger unavailable","Access blocked","Unsafe or damaged"};for(String r:rs){RadioButton rb=new RadioButton(this);rb.setText(r);rb.setTextSize(13);rb.setTextColor(INK);rb.setChecked(r.equals(report));rb.setOnClickListener(v->report=((RadioButton)v).getText().toString());choices.addView(rb);}add(choices);
    add(text("Service checked",12,MUTED));Spinner unit=new Spinner(this);String[] us={"Swap cabinet","Charging point","Site access","Payment or account"};unit.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,us));add(unit);add(text("Optional note",12,MUTED));EditText note=new EditText(this);note.setHint("Gate closed, no charged batteries, payment failed...");note.setMaxLines(3);note.setTextSize(12);note.setBackground(bg(SURFACE,dp(12)));pad(note,dp(10),dp(4),dp(10),dp(4));add(note);
    if(!reports.isEmpty()){LinearLayout log=box();log.addView(text("Local report queue",13,INK));for(int i=Math.max(0,reports.size()-2);i<reports.size();i++)log.addView(text("• "+reports.get(i),11,MUTED));add(log);}LinearLayout safe=box();safe.setBackground(bg(Color.rgb(255,243,223),dp(14)));safe.addView(text("Privacy first",13,INK));safe.addView(text("No personal trip history or contacts are attached. A report is queued, not labelled as live operator status.",11,MUTED));add(safe);
    LinearLayout actions=new LinearLayout(this);Button save=btn("Save report offline",true);save.setOnClickListener(v->{String n=note.getText().toString().trim();reports.add(active+" — "+report+" · "+unit.getSelectedItem()+(n.isEmpty()?"":" · "+n));showTrip();feedback.setText("Report saved offline and queued for review.");});actions.addView(save,new LinearLayout.LayoutParams(0,-2,1));Button back=btn("Back",false);back.setOnClickListener(v->showTrip());actions.addView(back,new LinearLayout.LayoutParams(0,-2,1));add(actions);}
}
